drills.solution:
const CURRENCIES = new Set(['EUR', 'USD', 'GBP']);
const fail = (error) => ({ ok: false, error });

export function parseEvent(input) {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) return fail('event must be an object');
  if (input.type === 'signup') {
    const { email } = input;
    if (typeof email !== 'string' || !/^[^@]+@[^@]+$/.test(email)) return fail('signup needs a valid email');
    return { ok: true, event: { type: 'signup', email } };
  }
  if (input.type === 'purchase') {
    const { amountCents, currency } = input;
    if (!Number.isInteger(amountCents) || amountCents <= 0) return fail('amountCents must be a positive whole number');
    if (!CURRENCIES.has(currency)) return fail('unsupported currency');
    return { ok: true, event: { type: 'purchase', amountCents, currency } };
  }
  return fail('unknown event type');
}

tests.code:
for (const bad of [
  { type: 'signup', email: 'no-at-sign' },
  { type: 'signup', email: 'a@b@c' },
  { type: 'signup', email: 42 },
  { type: 'purchase', amountCents: 0, currency: 'EUR' },
  { type: 'purchase', amountCents: 9.99, currency: 'EUR' },
  { type: 'purchase', amountCents: '1999', currency: 'EUR' },
  { type: 'purchase', amountCents: 100, currency: 'JPY' },
]) {
  const r = mod.parseEvent(bad);
  assert.equal(r.ok, false, JSON.stringify(bad));
  assert.ok(typeof r.error === 'string' && r.error.length > 0);
}

for (const bad of [null, undefined, 'signup', 42, [], { type: 'refund' }, {}]) {
  assert.equal(mod.parseEvent(bad).ok, false, String(bad));
}

drills.explanation:
Check that you have an object, branch on the tag, validate the fields of that branch, and build the output from scratch:

```js
if (input.type === 'purchase') {
  const { amountCents, currency } = input;
  if (!Number.isInteger(amountCents) || amountCents <= 0) return fail('amountCents must be a positive whole number');
  if (!CURRENCIES.has(currency)) return fail('unsupported currency');
  return { ok: true, event: { type: 'purchase', amountCents, currency } };
}
```

Returning `{ ...input }` from the signup branch keeps "a valid purchase" and the rejection tests green, but "a valid signup, extra keys dropped" fails: copying unknown keys is how mass-assignment bugs (`admin: true`) get in. Testing only `typeof input !== 'object'` instead of also checking `input === null` makes "non-objects and unknown tags are invalid, never thrown" fail, since reading `null.type` throws. A loose email pattern such as `/.+@.+/` accepts `a@b@c`, and "variant fields are checked" fails.

